   const r=row.rating!,date=sourceDate(r.at),few=hasFewRatings(r),cached=r.cacheStale||r.cacheDegraded||(row.source===source&&states[source]==='error');
   return row.name+' '+r.score!.toFixed(1)+'/'+row.scale+' · '+ratingCountLabel(r.count,locale,row.source)+(few?' · '+ratingCountQualification(locale,row.source):'')+(cached?' · '+(locale==='ja'?'前回の取得データ':locale==='en'?'Last successful data':'上次成功数据'):'')+(date?' · '+(r.sourceKey==='bangumi-archive'?(locale==='ja'?'アーカイブ基準日 ':locale==='en'?'Archive as of ':'档案截至 '):(locale==='ja'?'取得 ':locale==='en'?'Fetched ':'读取于 '))+date+' UTC':'');
