{pagedRanking&&ranking.coverage&&<section className="ranking-coverage" aria-label={locale==='ja'?'ランキングの収録範囲':locale==='en'?'Ranking coverage':'榜单收录范围'}><p>{rankSource==='bgm'?(locale==='ja'?`収録済み歴代作品の上位 ${ranking.total} 作品`:locale==='en'?`Best-ranked collected historical titles · ${ranking.total}`:`已收录历年作品 · 高分 ${ranking.total} 部`):(locale==='ja'?`Kitsu：収録 ${ranking.coverage.collectedCandidates} 件中、条件に合う ${ranking.total} 作品`:locale==='en'?`Kitsu: ${ranking.total} matches from ${ranking.coverage.collectedCandidates} collected records`:`Kitsu：已收录 ${ranking.coverage.collectedCandidates} 条，符合条件 ${ranking.total} 部`)}</p>{ranking.coverage.cacheDegraded&&<p>{locale==='ja'?'直近の取得に失敗したため、最後に取得できた資料を表示しています。':locale==='en'?'The last source check failed; these are the last acquired records.':'最近一次源站读取失败，当前保留最近成功取得的资料。'}</p>}<details className="system-disclosure"><summary>{locale==='ja'?'出典・日付・収録範囲':locale==='en'?'Source, dates and coverage':'来源、日期与范围'}</summary><p>{rankSource==='bgm'?(locale==='ja'?'保有アーカイブ内を元サイト順位で並べています。元サイト全体の最新Top500ではありません。':locale==='en'?'Ordered by original Bangumi rank within the collected archive. This is not a complete live global Top500.':'按已有档案中的 Bangumi 原始名次排序，不代表全站实时完整 Top500。'):(locale==='ja'?'元サイトには未収録の作品があります。取得できた資料だけを表示し、別サイトの点数では補いません。':locale==='en'?'More titles exist at the source than are collected here. Only acquired source records are shown.':'源站还有未收录的作品；这里只显示实际取得的资料，不用其他网站分数补位。')}</p><p>{locale==='ja'?'資料日時：':locale==='en'?'Source dates: ':'资料时间：'}{ranking.coverage.sourceDateRange.map(value=>sourceDate(value)).join(' – ')} UTC</p><p>{locale==='ja'?'条件一致：':locale==='en'?'Matching collected titles: ':'已收录且符合条件：'}{ranking.coverage.matchingTitles} · {locale==='ja'?'表示上限：':locale==='en'?'Window limit: ':'展示上限：'}500</p>{ranking.coverage.sourceUrl&&<a href={safe(ranking.coverage.sourceUrl)} target="_blank" rel="noreferrer">{tr('原始来源')}<ExternalLink size={14}/></a>}</details></section>}

